const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileCanonicalReacquisitionPresentation(input, reducedMotion = false) { const release = clamp01(input.release), pressure = clamp01(input.pressure), reacquire = clamp01(release * (1 - pressure * .18) + (input.critical ? .12 : 0)); return { reacquire, bodyScale: 1, trailScale: Math.max(input.critical ? .82 : .56, .56 + .44 * reacquire) * (reducedMotion ? .96 : 1), directionScale: Math.max(input.critical ? .9 : .72, .72 + .28 * reacquire), presentationOnly: true }; }
