export function hazardCanonicalReacquisitionPresentation(input, reducedFlash = false) { const release = clamp01(input.release), pressure = clamp01(input.pressure), reacquire = clamp01(release * (1 - pressure * .2) + (input.critical ? .08 : 0)), flash = reducedFlash ? .9 : 1; return { reacquire, fillScale: .48 + .46 * reacquire, fillAlphaScale: (.28 + .62 * reacquire) * flash, edgeAlphaScale: input.telegraph ? Math.max(input.critical ? .95 : .93, .99 * (reducedFlash ? .98 : 1)) : .72 + .26 * reacquire, presentationOnly: true }; }
export function safeLaneCanonicalReacquisitionPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), release = clamp01(input.release), pressure = clamp01(input.pressure), hold = clamp01(pressure * (1 - release)); return { pathAlphaFloor: input.visible ? Math.max(.93, .91 + confidence * .06) : 0, safeLaneScale: input.visible ? 1 + hold * (.06 + .04 * confidence) * (reducedFlash ? .78 : 1) : 1, staleContourScale: input.visible ? Math.max(.72, 1 - hold * .2) : 1, presentationOnly: true }; }
